import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"ماحولیاتی تحفظ کا قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/46-环境保护法.md","filePath":"ur/46-环境保护法.md"}'),e={name:"ur/46-环境保护法.md"};function i(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="ماحولیاتی-تحفظ-کا-قانون" tabindex="-1">ماحولیاتی تحفظ کا قانون <a class="header-anchor" href="#ماحولیاتی-تحفظ-کا-قانون" aria-label="Permalink to &quot;ماحولیاتی تحفظ کا قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>46</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>ماحولیاتی تحفظ، کائنات کی اصل، ماحولیاتی سمبیوسس، پائیدار ترقی، آلودگی کی روک تھام اور کنٹرول</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《ماحولیاتی تحفظ کا قانون》 اینکر سمبیوسس تہذیب کے پانچ معاون قوانین میں سے ایک ہے، اور اس کا مقصد ہینگیوانژو کے ماحولیاتی ماحول اور کائنات کی اصل کی حفاظت کرنا، &quot;سمبیوسس ارتقاء، پائیدار ترقی&quot; کے ماحولیاتی انتظام کا تصور قائم کرنا، لوٹ مار کی ترقی کے ذریعے کائنات کے ماحولیاتی نظام کی تباہی کی روک تھام کرنا، اور تمام نسلوں کی مشترکہ ترقی کے لیے بقا کی بنیاد کی حفاظت کرنا ہے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>اصل کی حفاظت کا اصول</td><td>کائنات کی اصل تمام زندگی اور ارتقاء کی بنیاد ہے، اسے ترجیحی طور پر محفوظ رکھنا چاہیے، اور تباہ کن کان کنی ممنوع ہے</td></tr><tr><td>ماحولیاتی سمبیوسس کا اصول</td><td>انسان اور فطرت، ہر نسل اور ماحولیاتی نظام سمبیوسس کے تعلق میں ہیں، اور ماحولیات کو تباہ کرنا اپنی بقا کی بنیاد کو تباہ کرنا ہے</td></tr><tr><td>پائیداری کا اصول</td><td>تمام ترقی کی سرگرمیوں کو موجودہ اور آنے والی نسلوں کے مفادات کو یکجا کرنا چاہیے، اور ضرورت سے زیادہ استعمال کی مخالفت کرنی چاہیے</td></tr><tr><td>روک تھام بنیادی کا اصول</td><td>ماحولیاتی تحفظ روک تھام کو بنیادی بناتا ہے، ماحولیاتی اثر تشخیص کا نظام قائم کرتا ہے، اور آلودگی کے واقعات کی روک تھام کرتا ہے</td></tr><tr><td>آلودہ کرنے والے کی ذمہ داری کا اصول</td><td>ماحولیاتی آلودگی اور ماحولیاتی تباہی پیدا کرنے والے معاملے کو ضرور صفائی اور معاوضے کی ذمہ داری اٹھانی چاہیے</td></tr><tr><td>عوامی شرکت کا اصول</td><td>عوام کو ماحولیاتی تحفظ میں حصہ لینے کی ترغیب دینا، عوام کے ماحولیاتی معلومات کے حق اور شرکت کے حق کی ضمانت کرنا</td></tr><tr><td>بین位面 تعاون کا اصول</td><td>ماحولیاتی تحفظ بین位面 تعاون کے ذریعے آگے بڑھتا ہے، بین位面 ماحولیاتی انتظام تعاون کا نظام قائم کرنا</td></tr></tbody></table><h2 id="ثانياً-ماحولیاتی-تحفظ-کا-دائرہ" tabindex="-1">ثانياً. ماحولیاتی تحفظ کا دائرہ <a class="header-anchor" href="#ثانياً-ماحولیاتی-تحفظ-کا-دائرہ" aria-label="Permalink to &quot;ثانياً. ماحولیاتی تحفظ کا دائرہ&quot;">​</a></h2><p>اس قانون کے ذریعے محفوظ کئے جانے والے ماحولیاتی دائرے میں ہینگیوانژو کے اندر تمام ماحولیاتی نظام اور ماحولیاتی عناصر شامل ہیں:</p><ol><li><strong>ماحولیاتی ماحول</strong>: ہر سیارے کا ماحول، توانائی کی تہہ کی توانائی کی گھنٹہ اور اجزاء کا توازن شامل ہے۔</li><li><strong>پانی کا ماحول</strong>: زمینی سطح کے پانی، زیر زمین پانی، سمندر،位面 کے درمیان توانائی کے آبی علاقے کے پانی کے معیار اور پانی کی مقدار شامل ہے۔</li><li><strong>مٹی کا ماحول</strong>: خشکی کی مٹی، سادھنہ وسائل کی کان کی رگوں کی مٹی کا معیار اور زرخیزی شامل ہے۔</li><li><strong>حیاتیاتی تنوع</strong>: تمام جانوروں اور پودوں، جرثوموں، عجیب زندگی کی نسلوں کی تحفظ اور رہائش گاہوں کی تحفظ شامل ہے۔</li><li><strong>توانائی کا ماحول</strong>: آسمان اور زمین کی روحانی توانائی، اصل کی توانائی، قوانین کے ٹکڑوں کی گھنٹہ اور تقسیم کا توازن شامل ہے۔</li><li><strong>جگہ کا ماحول</strong>:位面 جگہ کے استحکام، جگہ کے دراڑ، جوڑی ہوئی جگہ کے ماحولیاتی تحفظ شامل ہے۔</li><li><strong>شعور کے دائرے کا ماحول</strong>: اجتماعی شعور کی جگہ کی معلومات کی صفائی اور روحانی آلودگی کی روک تھام شامل ہے۔</li></ol><h2 id="ثالثاً-اہم-نظام" tabindex="-1">ثالثاً. اہم نظام <a class="header-anchor" href="#ثالثاً-اہم-نظام" aria-label="Permalink to &quot;ثالثاً. اہم نظام&quot;">​</a></h2><h3 id="_1-ماحولیاتی-اثر-تشخیص-کا-نظام" tabindex="-1">(1) ماحولیاتی اثر تشخیص کا نظام <a class="header-anchor" href="#_1-ماحولیاتی-اثر-تشخیص-کا-نظام" aria-label="Permalink to &quot;(1) ماحولیاتی اثر تشخیص کا نظام&quot;">​</a></h3><p>تمام ممکنہ ماحولیات پر اہم اثر ڈالنے والی ترقی اور تعمیر کے منصوبوں کو کام شروع کرنے سے پہلے ضرور ماحولیاتی اثر تشخیص سے گزرنا چاہیے۔ تشخیص کے مواد میں شامل ہیں: منصوبے کا ماحول، پانی، مٹی، جاندار، توانائی، جگہ وغیرہ ماحولیاتی عناصر پر اثر، روک تھام اور کم کرنے کے اقدامات، ماحولیاتی خطرہ تشخیص وغیرہ۔ ماحولیاتی اثر تشخیص میں پاس نہ کرنے والے منصوبے کام شروع نہیں کر سکتے۔</p><h3 id="_2-آلودگی-خارج-کرنے-کا-لائسنس-اور-کل-مقدار-کنٹرول-کا-نظام" tabindex="-1">(2) آلودگی خارج کرنے کا لائسنس اور کل مقدار کنٹرول کا نظام <a class="header-anchor" href="#_2-آلودگی-خارج-کرنے-کا-لائسنس-اور-کل-مقدار-کنٹرول-کا-نظام" aria-label="Permalink to &quot;(2) آلودگی خارج کرنے کا لائسنس اور کل مقدار کنٹرول کا نظام&quot;">​</a></h3><p>ریاست آلودہ مادوں کے اخراج کے لیے لائسنس کا انتظام اور کل مقدار کنٹرول نافذ کرتی ہے۔ آلودگی خارج کرنے والی اکائیوں کو ضرور آلودگی خارج کرنے کا لائسنس حاصل کرنا چاہیے، اور لائسنس میں طے شدہ اقسام، گھنٹہ، کل مقدار کے مطابق آلودہ مادے خارج کرنے چاہئیں۔ ریاست ماحولیاتی برداشت کی صلاحیت کے مطابق ہر علاقے، ہر位面 کے آلودہ مادوں کے اخراج کی کل مقدار طے کرتی ہے، اور مرحلہ وار تقسیم کر کے نافذ کرتی ہے۔</p><h3 id="_3-ماحولیاتی-تحفظ-کی-سرخ-لکیر-کا-نظام" tabindex="-1">(3) ماحولیاتی تحفظ کی سرخ لکیر کا نظام <a class="header-anchor" href="#_3-ماحولیاتی-تحفظ-کی-سرخ-لکیر-کا-نظام" aria-label="Permalink to &quot;(3) ماحولیاتی تحفظ کی سرخ لکیر کا نظام&quot;">​</a></h3><p>ریاست خاص ماحولیاتی قیمت والے علاقوں میں ماحولیاتی تحفظ کی سرخ لکیر طے کرتی ہے، اور اس میں شامل ہیں:</p><table tabindex="0"><thead><tr><th>سرخ لکیر کی قسم</th><th>تحفظ کا مواد</th></tr></thead><tbody><tr><td>اصل تحفظ کا علاقہ</td><td>کائنات کی اصل توانائی کا بنیادی پیداواری علاقہ، تمام ترقی کی سرگرمیاں ممنوع</td></tr><tr><td>نسلوں کی رہائش گاہ</td><td>نایاب خطرے سے دوچار نسلوں کی بنیادی رہائش گاہ، تباہی اور مداخلت ممنوع</td></tr><tr><td>ماحولیاتی رکاوٹ کا علاقہ</td><td>علاقائی ماحولیاتی توازن کو برقرار رکھنے والا اہم ماحولیاتی نظام، ترقی محدود</td></tr><tr><td>سادھنہ کی مقدس جگہ</td><td>خاص سادھنہ قیمت والی توانائی سے بھرا ہوا علاقہ، تحفظ کے ساتھ استعمال نافذ</td></tr><tr><td>位面 کی سرحدی زون</td><td>位面 کے درمیان ماحولیاتی منتقلی زون، جگہ کی تباہ کن ترقی ممنوع</td></tr></tbody></table><h3 id="_4-ماحولیاتی-نگرانی-اور-انتباہ-کا-نظام" tabindex="-1">(4) ماحولیاتی نگرانی اور انتباہ کا نظام <a class="header-anchor" href="#_4-ماحولیاتی-نگرانی-اور-انتباہ-کا-نظام" aria-label="Permalink to &quot;(4) ماحولیاتی نگرانی اور انتباہ کا نظام&quot;">​</a></h3><p>ریاست پوری کائنات پر محیط ماحولیاتی نگرانی نیٹ ورک قائم کرتی ہے، اور ہر ماحولیاتی عنصر کی تبدیلی کی صورتحال کو ریئل ٹائم نگرانی کرتی ہے۔ ممکنہ سنگین ماحولیاتی آلودگی اور ماحولیاتی تباہی کے واقعات کے لیے، انتباہ کا نظام قائم کرتی ہے، بروقت انتباہ کی معلومات جاری کرتی ہے اور ایمرجنسی ردعمل شروع کرتی ہے۔</p><h3 id="_5-ماحولیاتی-معاوضے-کا-نظام" tabindex="-1">(5) ماحولیاتی معاوضے کا نظام <a class="header-anchor" href="#_5-ماحولیاتی-معاوضے-کا-نظام" aria-label="Permalink to &quot;(5) ماحولیاتی معاوضے کا نظام&quot;">​</a></h3><p>ماحولیاتی تحفظ کی وجہ سے ترقی محدود علاقوں اور گروپوں کو ماحولیاتی معاوضہ حاصل کرنے کا حق ہے۔ ماحولیاتی معاوضے کے فنڈز عوامی جمع اور وسائل کی ترقی کی آمدنی سے اٹھائے جاتے ہیں، اور معاوضے والے علاقے کی معاشی ترقی اور رہائشیوں کی زندگی میں بہتری کے لیے استعمال ہوتے ہیں۔</p><h2 id="رابعاً-سادھنہ-کی-سرگرمیوں-کا-ماحولیاتی-ضابطہ" tabindex="-1">رابعاً. سادھنہ کی سرگرمیوں کا ماحولیاتی ضابطہ <a class="header-anchor" href="#رابعاً-سادھنہ-کی-سرگرمیوں-کا-ماحولیاتی-ضابطہ" aria-label="Permalink to &quot;رابعاً. سادھنہ کی سرگرمیوں کا ماحولیاتی ضابطہ&quot;">​</a></h2><p>سادھنہ کی سرگرمیوں کا ماحولیات پر اثر ہینگیوانژو کے ماحولیاتی تحفظ کا خاص شعبہ ہے، اور یہ قانون خاص طور پر ضابطے کی دفعات قائم کرتا ہے:</p><ol><li><strong>توانائی کی کان کنی کا ضابطہ</strong>: سادھنہ وسائل کی کان کنی کو ضرور پائیداری کے اصول پر پورا اترنا چاہیے، اور تباہ کن کان کنی جو توانائی کی کمی کا باعث بنتی ہے وہ ممنوع ہے۔ کان کنی کی مقدار علاقائی توانائی کی قدرتی بحالی کی رفتار سے تجاوز نہیں کر سکتی۔</li><li><strong>سادھنہ کے فضلے کا انتظام</strong>: سادھنہ کے عمل میں پیدا ہونے والی توانائی کی باقیات، فضلہ ادویات، ٹوٹے ہوئے آلات وغیرہ کو ضرور طے شدہ کے مطابق سنبھالنا چاہیے، اور بے ترتیب طریقے سے پھینک کر توانائی کی آلودگی پیدا کرنا ممنوع ہے۔</li><li><strong>اعلیٰ سطحی سادھنہ ماحولیاتی تشخیص</strong>: اعلیٰ سطحی سادھک کی پیشرفت اور تنہائی ارد گرد کے ماحولیات پر اہم اثر ڈال سکتی ہے، اور اس سے پہلے ضرور ماحولیاتی تشخیص کرنی چاہیے اور تحفظی اقدامات کرنے چاہئیں۔</li><li><strong>位面 ترقی کا لائسنس</strong>: نئے位面 کی ترقی کو ضرور ماحولیاتی تشخیص اور ماحولیاتی تفتیش سے گزرنا چاہیے، اور ماحولیاتی تحفظ کی منصوبہ بندی بنانے کے بعد ہی شروع کی جا سکتی ہے۔</li><li><strong>عجیب زندگی کی رہائش گاہوں کی تحفظ</strong>: عجیب زندگی کی رہائش گاہوں کو ماحولیاتی تحفظ کی سرخ لکیر میں شامل کیا گیا ہے، اور لائسنس کے بغیر دریافت اور ترقی ممنوع ہے۔</li></ol><h2 id="خامساً-قانونی-ذمہ-داری" tabindex="-1">خامساً. قانونی ذمہ داری <a class="header-anchor" href="#خامساً-قانونی-ذمہ-داری" aria-label="Permalink to &quot;خامساً. قانونی ذمہ داری&quot;">​</a></h2><p>اس قانون کی دفعات کی خلاف ورزی کرنے والے کارروائیاں جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائیں گی:</p><ul><li>ماحولیاتی اثر تشخیص میں پاس نہ کر کے بغیر اجازت کام شروع کرنے پر، تعمیر بند کرنے کا حکم، اصل حالت میں واپس لانا اور جرمانہ۔</li><li>معیار سے تجاوز کر کے آلودہ مادے خارج کرنے پر، مقررہ وقت میں صفائی کا حکم اور جرمانہ، سنگین صورتوں میں کاروبار بند کرنے کا حکم۔</li><li>ماحولیاتی تحفظ کی سرخ لکیر کو تباہ کرنے پر، اصل حالت میں واپس لانے کا حکم اور جرمانہ، سنگین صورتوں میں فوجداری ذمہ داری عائد۔</li><li>سادھنہ وسائل کی تباہ کن کان کنی کرنے پر، غیر قانونی آمدنی ضبط اور جرمانہ، کان کنی کا لائسنس منسوخ۔</li><li>سنگین ماحولیاتی آلودگی کا حادثہ پیدا کرنے پر، معاوضے کی ذمہ داری، اگر جرم تشکیل دے تو فوجداری ذمہ داری عائد۔</li><li>ماحولیاتی نگرانی کا عملہ لاپرواہی کرتا ہے، اختیارات کا غلط استعمال کرتا ہے، اسے سزا دی جائے گی، اگر جرم تشکیل دے تو فوجداری ذمہ داری عائد۔</li></ul><h2 id="سادساً-عوامی-شرکت-اور-ماحولیاتی-عوامی-مفاد-کا-مقدمہ" tabindex="-1">سادساً. عوامی شرکت اور ماحولیاتی عوامی مفاد کا مقدمہ <a class="header-anchor" href="#سادساً-عوامی-شرکت-اور-ماحولیاتی-عوامی-مفاد-کا-مقدمہ" aria-label="Permalink to &quot;سادساً. عوامی شرکت اور ماحولیاتی عوامی مفاد کا مقدمہ&quot;">​</a></h2><p>عوام کو ماحولیاتی تحفظ میں حصہ لینے کا حق ہے، اور مخصوص ذرائع میں شامل ہیں:</p><ol><li>ماحولیاتی اثر تشخیص کے منصوبے پر رائے اور تجاویز دینا۔</li><li>ماحولیاتی آلودگی اور ماحولیاتی تباہی کے کارروائیوں کی اطلاع اور شکایت کرنا۔</li><li>قانون کے مطابق ماحولیاتی تحفظ کی تنظیمیں قائم کرنا، ماحولیاتی نگرانی اور عوامی مفاد کی سرگرمیوں میں حصہ لینا۔</li><li>ماحولیاتی آلودگی، ماحولیاتی تباہی جو عوامی مفاد کو نقصان پہنچاتی ہے، اس صورت میں ماحولیاتی تحفظ کی تنظیمیں سمبیوسس عدالت میں ماحولیاتی عوامی مفاد کا مقدمہ دائر کر سکتی ہیں۔</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《ماحولیاتی تحفظ کا قانون》 اینکر سمبیوسس تہذیب کے پائیدار ترقی کے تصور کی قانونی ضمانت ہے۔ یہ ماحولیاتی اثر تشخیص، ماحولیاتی تحفظ کی سرخ لکیر، کل مقدار کنٹرول وغیرہ نظام قائم کرنے کے ذریعے، ماحولیاتی تحفظ کو تمام ترقی اور سادھنہ کی سرگرمیوں میں ضم کرتا ہے، اور کائنات کی اصل اور ماحولیاتی نظام کی پائیداری کو یقینی بناتا ہے، تمام نسلوں کی مشترکہ ترقی کے لیے ابدی بقا کی بنیاد کی حفاظت کرتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>39-住房与环境保障 (رہائش اور ماحولیاتی تحفظ)</li><li>15-能量循环与转化法则 (توانائی کے چکر اور تبدیلی کا قانون)</li><li>53-奇特生命识别标准 (عجیب زندگی کی شناخت کا معیار)</li></ul>',34)])])}const _=a(e,[["render",i]]);export{c as __pageData,_ as default};
